<?php $action=$post?url('admin/posts/'.$post['id']):url('admin/posts');?><header class="admin-header"><div><p class="eyebrow">Editor</p><h1><?= e($title) ?></h1></div></header><?php if(!empty($_SESSION['_error'])):?><div class="alert error"><?= e($_SESSION['_error']);unset($_SESSION['_error']) ?></div><?php endif?><form class="editor" method="post" action="<?= e($action) ?>" data-unsaved><?= csrf_field() ?><div class="editor-main panel"><label>Title<input name="title" value="<?= e($post['title']??'') ?>" maxlength="255" required data-slug-source></label><label>Slug<input name="slug" value="<?= e($post['slug']??'') ?>" maxlength="191" data-slug-target></label><label>Excerpt<textarea name="excerpt" rows="3" maxlength="1000"><?= e($post['excerpt']??'') ?></textarea></label><div class="editor-tabs"><button type="button" data-tab="write" class="active">Write</button><button type="button" data-tab="preview">Preview</button></div><div class="split-editor"><label class="write-pane">Markdown<textarea name="markdown_content" rows="24" required data-markdown><?= e($post['markdown_content']??'') ?></textarea></label><section class="preview-pane markdown" aria-live="polite"><p class="muted">Preview updates as you type.</p></section></div></div><aside class="editor-side panel"><label>Status<select name="status"><option value="draft">Draft</option><option value="scheduled" <?= ($post['status']??'')==='scheduled'?'selected':'' ?>>Scheduled</option><option value="published" <?= ($post['status']??'')==='published'?'selected':'' ?>>Published</option><option value="archived" <?= ($post['status']??'')==='archived'?'selected':'' ?>>Archived</option></select></label><label>Schedule at<input type="datetime-local" name="scheduled_at" value="<?= e(isset($post['scheduled_at'])&&$post['scheduled_at']?date('Y-m-d\TH:i',strtotime($post['scheduled_at'])):'') ?>"></label><label>Category<select name="category_id"><option value="">None</option><?php foreach($categories as $c):?><option value="<?= (int)$c['id'] ?>" <?= (int)($post['category_id']??0)===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach?></select></label><h2>SEO</h2><label>Meta title<input name="meta_title" value="<?= e($post['meta_title']??'') ?>" maxlength="255"></label><label>Meta description<textarea name="meta_description" rows="3" maxlength="500"><?= e($post['meta_description']??'') ?></textarea></label><label>Canonical URL<input type="url" name="canonical_url" value="<?= e($post['canonical_url']??'') ?>"></label><label class="check"><input type="checkbox" name="robots_index" <?= !isset($post)||$post['robots_index']?'checked':'' ?>> Allow indexing</label><label class="check"><input type="checkbox" name="robots_follow" <?= !isset($post)||$post['robots_follow']?'checked':'' ?>> Follow links</label><button class="button full">Save post</button></aside></form>
